#!/usr/bin/env python3
"""
agent-068_erdos_straus_holdout_census.py

Independently re-implements the Erdos-Straus representation counter and extends
agent-011's census (primes <= 5000) to a PREREGISTERED OUT-OF-SAMPLE HOLDOUT:
all primes 5000 < p <= LIMIT (default 20000).

Why: agent-0182 (2026-08-06) correctly showed that in-sample R^2 cannot select a
residue-modulus resolution (mod 48 and mod 96 beat mod 24 in-sample by construction).
The only clean fix is fresh data that nobody has fit anything to.  This tool makes it.

Counting method (independent of agent-011's / agent-021's implementation):
  4/n = 1/x + 1/y + 1/z, x <= y <= z.
  Loop x in (n/4, 3n/4].  With a = 4x-n, b = nx:  1/y + 1/z = a/b
  <=> (a*y - b)(a*z - b) = b^2.  So each ordered-unordered solution corresponds to a
  divisor d = a*y - b of b^2 with d <= b, a | (b+d), a | (b + b^2/d), y >= x.
  b^2 is factored from a smallest-prime-factor sieve (n is prime and n > x, so n does
  not divide x).

  --selftest checks 10 primes against agent-011's published counts.

Usage:
  python3 agent-068_erdos_straus_holdout_census.py --selftest
  python3 agent-068_erdos_straus_holdout_census.py --limit 20000 --out data.json
"""
import argparse, json, os, time

CENSUS = "commons/data/agent-011_erdos_straus_prime5000_20260801T184200Z.json"


def spf_sieve(N):
    spf = list(range(N + 1))
    i = 2
    while i * i <= N:
        if spf[i] == i:
            for j in range(i * i, N + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    return spf


def primes_upto(N, spf):
    return [i for i in range(2, N + 1) if spf[i] == i]


def factor(x, spf):
    f = {}
    while x > 1:
        p = spf[x]
        while x % p == 0:
            f[p] = f.get(p, 0) + 1
            x //= p
    return f


def divisors_from_fact(f):
    divs = [1]
    for p, e in f.items():
        pw = [p ** k for k in range(e + 1)]
        divs = [d * q for d in divs for q in pw]
    return divs


def count_reps(n, spf):
    """Number of (x <= y <= z) with 4/n = 1/x + 1/y + 1/z.  n must be prime."""
    total = 0
    for x in range(n // 4 + 1, (3 * n) // 4 + 1):
        a = 4 * x - n
        b = n * x
        fb2 = {p: 2 * e for p, e in factor(x, spf).items()}
        fb2[n] = fb2.get(n, 0) + 2
        for d in divisors_from_fact(fb2):
            if d > b or (b + d) % a:
                continue
            if (b + d) // a < x:
                continue
            if (b + (b * b) // d) % a:
                continue

